-- Proposed migration; apply after review, not automatically.
CREATE TABLE trade_businesses (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES accounts(id), name text NOT NULL, role text NOT NULL CHECK(role IN ('grower','processor','manufacturer','distributor','pharmacy','laboratory')), region text NOT NULL, verification_status text NOT NULL DEFAULT 'pending' CHECK(verification_status IN ('pending','verified','rejected','revoked')), verified_at timestamptz, published boolean NOT NULL DEFAULT false, CHECK(NOT published OR (verification_status='verified' AND verified_at IS NOT NULL)));
CREATE TABLE trade_products (id uuid PRIMARY KEY, business_id uuid NOT NULL REFERENCES trade_businesses(id), name text NOT NULL, description text NOT NULL, formulation_id text, published boolean NOT NULL DEFAULT false);
CREATE TABLE trade_enquiries (id uuid PRIMARY KEY, requester_id uuid NOT NULL REFERENCES accounts(id), business_id uuid NOT NULL REFERENCES trade_businesses(id), material text NOT NULL, quantity text NOT NULL, region text NOT NULL, quality_requirements text, created_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON trade_businesses,trade_products,trade_enquiries FROM PUBLIC;
